import { defineConfig } from 'astro/config';

// Same conventions as openbiblestories.org and translationcore.com: static
// output, trailing slashes everywhere, uncompressed HTML. BT Servant is
// English-only, so there is no i18n routing.
//
// `site` is the canonical origin. It drives every canonical, Open Graph,
// sitemap, JSON-LD and /llms.txt URL, so it must match SITE_URL in
// src/data/site.ts and the www → apex zone rule (docs/deployment.md).
//
// Sitemaps are generated by src/pages/sitemap-*.xml.ts (an index plus one
// file for the pages) rather than @astrojs/sitemap, matching the sister sites.
export default defineConfig({
  site: 'https://btservant.ai',
  devToolbar: { enabled: false },
  trailingSlash: 'always',

  // Keep the built HTML uncompressed so it stays diffable against the
  // hand-written pages this site was migrated from.
  compressHTML: false,
});
